                r, c = rotate_90_cw(r, c, center)
            if 0 <= r < 27 and 0 <= c < 11:
                output.add((r, c))
    results[center] = len(output)

print("Number of in-bounds output points per center:")
for c, n in sorted(results.items()):
    print(f"  {c}: {n} points")

