center = (4.5, 7.5)

def rotate_ccw(r, c):
    cr, cc = center
    r_new = int(cr + c - cc)  # c - 3
    c_new = int(cc + cc - r)  # 15 - r
    return (r_new, c_new)

input_ones = [(1, 10), (1, 12), (3, 8), (3, 9), (4, 9)]

# Generate CCW rotations
output_ccw = set()
for r, c in input_ones:
    for i in range(4):
        for _ in range(i):
            r, c = rotate_ccw(r, c)
        output_ccw.add((r, c))

# Build grid
grid = [[bg]*width for _ in range(height)]
for r in [4, 5]:
    for c in [7, 8]:
        grid[r][c] = 5
for r, c in sorted(output_ccw):
    if 0 <= r < height and 0 <= c < width:
        grid[r][c] = 1

# Submit CCW version
